CREATE TYPE "ERPUserStatus" AS ENUM ('ACTIVE','INACTIVE');
CREATE TYPE "AttendanceStatus" AS ENUM ('PRESENT','ABSENT');
CREATE TYPE "ResultStatus" AS ENUM ('DRAFT','PUBLISHED');

CREATE TABLE "Department" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Department_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Department_code_key" ON "Department"("code");
CREATE TABLE "Programme" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"code" TEXT NOT NULL,"departmentId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Programme_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Programme_code_key" ON "Programme"("code"); CREATE INDEX "Programme_departmentId_idx" ON "Programme"("departmentId");
CREATE TABLE "Semester" ("id" TEXT NOT NULL,"number" INTEGER NOT NULL,"programmeId" TEXT NOT NULL,CONSTRAINT "Semester_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Semester_programmeId_number_key" ON "Semester"("programmeId","number");
CREATE TABLE "Subject" ("id" TEXT NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"credits" INTEGER NOT NULL DEFAULT 0,"departmentId" TEXT NOT NULL,"semesterId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Subject_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Subject_departmentId_code_key" ON "Subject"("departmentId","code");
CREATE TABLE "Faculty" ("id" TEXT NOT NULL,"employeeNumber" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"phone" TEXT,"departmentId" TEXT NOT NULL,"status" "ERPUserStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Faculty_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Faculty_employeeNumber_key" ON "Faculty"("employeeNumber"); CREATE UNIQUE INDEX "Faculty_email_key" ON "Faculty"("email");
CREATE TABLE "FacultySubject" ("id" TEXT NOT NULL,"facultyId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,CONSTRAINT "FacultySubject_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "FacultySubject_facultyId_subjectId_key" ON "FacultySubject"("facultyId","subjectId");
CREATE TABLE "Student" ("id" TEXT NOT NULL,"enrollmentNumber" TEXT NOT NULL,"admissionNumber" TEXT,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"photoUrl" TEXT,"email" TEXT,"phone" TEXT,"age" INTEGER,"address" TEXT,"departmentId" TEXT NOT NULL,"programmeId" TEXT NOT NULL,"semesterId" TEXT NOT NULL,"admissionYear" INTEGER,"status" "ERPUserStatus" NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Student_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Student_enrollmentNumber_key" ON "Student"("enrollmentNumber"); CREATE UNIQUE INDEX "Student_admissionNumber_key" ON "Student"("admissionNumber"); CREATE UNIQUE INDEX "Student_email_key" ON "Student"("email");
CREATE TABLE "Timetable" ("id" TEXT NOT NULL,"dayOfWeek" INTEGER NOT NULL,"startTime" TEXT NOT NULL,"endTime" TEXT NOT NULL,"room" TEXT,"subjectId" TEXT NOT NULL,"facultyId" TEXT NOT NULL,"studentId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Timetable_pkey" PRIMARY KEY ("id")); CREATE INDEX "Timetable_facultyId_dayOfWeek_idx" ON "Timetable"("facultyId","dayOfWeek"); CREATE INDEX "Timetable_studentId_dayOfWeek_idx" ON "Timetable"("studentId","dayOfWeek");
CREATE TABLE "Attendance" ("id" TEXT NOT NULL,"date" TIMESTAMP(3) NOT NULL,"period" INTEGER NOT NULL,"status" "AttendanceStatus" NOT NULL,"studentId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"facultyId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Attendance_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Attendance_studentId_subjectId_date_period_key" ON "Attendance"("studentId","subjectId","date","period"); CREATE INDEX "Attendance_studentId_date_idx" ON "Attendance"("studentId","date"); CREATE INDEX "Attendance_subjectId_date_idx" ON "Attendance"("subjectId","date");
CREATE TABLE "Result" ("id" TEXT NOT NULL,"semesterNumber" INTEGER NOT NULL,"sgpa" DOUBLE PRECISION,"cgpa" DOUBLE PRECISION,"status" "ResultStatus" NOT NULL DEFAULT 'DRAFT',"studentId" TEXT NOT NULL,"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Result_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Result_studentId_semesterNumber_key" ON "Result"("studentId","semesterNumber");
CREATE TABLE "ResultSubject" ("id" TEXT NOT NULL,"resultId" TEXT NOT NULL,"subjectId" TEXT NOT NULL,"marks" DOUBLE PRECISION,"grade" TEXT,"gradePoint" DOUBLE PRECISION,"credits" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "ResultSubject_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "ResultSubject_resultId_subjectId_key" ON "ResultSubject"("resultId","subjectId");
CREATE TABLE "FeeAccount" ("id" TEXT NOT NULL,"studentId" TEXT NOT NULL,"totalAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"paidAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"pendingAmount" DOUBLE PRECISION NOT NULL DEFAULT 0,"dueDate" TIMESTAMP(3),"updatedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FeeAccount_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "FeeAccount_studentId_key" ON "FeeAccount"("studentId");
CREATE TABLE "FeePayment" ("id" TEXT NOT NULL,"feeAccountId" TEXT NOT NULL,"amount" DOUBLE PRECISION NOT NULL,"paymentDate" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"reference" TEXT,"note" TEXT,CONSTRAINT "FeePayment_pkey" PRIMARY KEY ("id"));
ALTER TABLE "Programme" ADD CONSTRAINT "Programme_departmentId_fkey" FOREIGN KEY ("departmentId") REFERENCES "Department"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
